import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.CuUVYbLV.js";const m=JSON.parse('{"title":"已知限制","description":"rolebox v1.9.0 的已知限制清单——按子系统列出限制、撞上它的条件，以及可以采用的规避方式。","frontmatter":{"title":"已知限制","description":"rolebox v1.9.0 的已知限制清单——按子系统列出限制、撞上它的条件，以及可以采用的规避方式。"},"headers":[],"relativePath":"03-Reference/limitations.md","filePath":"03-Reference/limitations.md"}'),a={name:"03-Reference/limitations.md"};function r(i,t,l,s,h,n){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="已知限制-known-limitations" tabindex="-1">已知限制（Known Limitations） <a class="header-anchor" href="#已知限制-known-limitations" aria-label="Permalink to &quot;已知限制（Known Limitations）&quot;">​</a></h1><p>本页列出 rolebox v1.9.0 中确实会撞上的边界。每条都写成可判定的形式：<strong>限制</strong>是什么、<strong>什么情况下会撞上</strong>、<strong>怎么绕开</strong>。这里不区分「有意为之」与「暂时如此」——只回答「我现在会不会被卡住」。</p><blockquote><p>相关：<a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a>｜<a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a>｜<a href="/rolebox-docs/01-Overview/platform-harnesses.html">平台与 Harness</a>｜<a href="/rolebox-docs/04-Advanced/compatibility.html">兼容性</a></p></blockquote><h2 id="角色与函数模型" tabindex="-1">角色与函数模型 <a class="header-anchor" href="#角色与函数模型" aria-label="Permalink to &quot;角色与函数模型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>角色之间没有继承机制</td><td>想在角色 A 的 <code>role.yaml</code> 里继承角色 B 的配置——没有对应字段，只能在每个角色里重复声明</td><td>用技能（skills）与引用文档（references）共享知识；用子代理做组合。注意子代理<strong>会</strong>继承父角色的 <code>model</code>、<code>color</code>、<code>variant</code>、<code>temperature</code>、<code>top_p</code>、<code>permission</code>、<code>tools</code> 七个字段，未显式覆盖即沿用父值</td></tr><tr><td>会话内不能切换角色</td><td>会话已经以某个角色启动，想中途换成另一个角色继续干活</td><td>把要换的活交给子代理；或退出当前会话，以另一个角色重新开始</td></tr><tr><td>函数激活是会话级的</td><td>用激活前缀打开的函数的整个会话里保持激活，做不到「只对下一条消息生效」</td><td>用 <code>transitions</code> 配 <code>deactivate</code>，让函数在条件满足时自行停用；用 <code>disable_functions</code> 在角色级排除；把不同阶段放进不同子代理</td></tr><tr><td>内置条件不包含项目上下文</td><td>想「文件是 TypeScript 就激活这个函数」这类按项目结构判断的激活方式——内置条件只有会话与函数状态：<code>user_approval</code>、<code>artifact_exists</code>、<code>plan_todos_complete</code>、<code>plan_incomplete</code>、<code>evidence_met</code>、<code>tool_observed</code>、<code>signal_observed</code>、<code>turn_count</code>、<code>state_eq</code>（可用 <code>all</code> / <code>any</code> / <code>not</code> 组合）</td><td>通过扩展作用域 <code>conditions</code> 注册自定义条件模块（导出 <code>handler(arg, env)</code>）；或先用工具把项目特征写进 artifact 与运行时状态，再用 <code>artifact_exists</code>、<code>state_eq</code> 判断</td></tr><tr><td><code>--</code> 是保留分隔符</td><td>角色目录名里含 <code>--</code>（例如 <code>code--reviewer</code>）——该角色会被跳过，日志提示 <code>role ID must not contain &quot;--&quot;</code></td><td>用 <code>-</code>、<code>_</code>、<code>.</code> 之类分隔符；子代理 ID 里的 <code>--</code> 是系统拼出来的，不要手工使用</td></tr></tbody></table><h2 id="子代理与调度" tabindex="-1">子代理与调度 <a class="header-anchor" href="#子代理与调度" aria-label="Permalink to &quot;子代理与调度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>文件式子代理最多递归 3 层</td><td>目录嵌套到第 4 层（<code>subagents/&lt;子&gt;/subagents/&lt;孙&gt;/subagents/&lt;曾孙&gt;/subagents/&lt;玄孙&gt;/role.yaml</code>）时，该层的 <code>role.yaml</code> 不会被加载，且没有报错</td><td>把更深的层级内联声明在父级的 <code>subagents:</code> 字段里，或把深层子代理扁平化到中间层</td></tr><tr><td>后台任务 stale 超时默认 15 分钟</td><td>后台任务连续无进展超过 <code>backgroundStaleTimeoutMs</code>（默认 <code>900000</code> ms）即被判为 <code>timeout</code></td><td>在派发到该任务的图节点上声明 <code>budget.timeout_ms</code>（它成为该任务的硬超时，覆盖后台默认值）；或在 <code>role.yaml</code> 的 <code>dispatch:</code> 块里调整 <code>backgroundStaleTimeoutMs</code></td></tr><tr><td>同步提示词超时默认 10 分钟</td><td>同步调度（sync）等待子代理提示词完成，超过 <code>syncPromptTimeoutMs</code>（默认 <code>600000</code> ms）即失败</td><td>改为后台任务；或在 <code>dispatch:</code> 块里调整 <code>syncPromptTimeoutMs</code></td></tr><tr><td>终态任务记录只保留 30 分钟</td><td>任务结束后超过 <code>taskTtlMs</code>（默认 <code>1800000</code> ms），记录被清出：查不到、也无法再重试</td><td>需要留存就用 <code>task_export</code> 提前落盘；结果 sidecar 文件默认保留 1 小时（<code>resultRetentionMs</code>），同样会过期</td></tr><tr><td>结果物化超时 10 秒</td><td>抓取子代理结果超过 <code>materializeTimeoutMs</code>（默认 <code>10000</code> ms）时，结果引用上的 <code>fetchError</code> 记为 <code>timeout</code>、sidecar 留空</td><td>重试该任务；或让子代理把结果写进工作区文件，而不是只放在回复文本里</td></tr><tr><td>调度层不设并发槽位上限</td><td>一次派发大量后台任务时它们会直接全部启动；卡住的任务只能靠 stale 超时与看门狗（reconcile 15 秒、全局 sweep 30 秒）兜底回收</td><td>在派发侧自行控制并发；给每个图节点设置合理的 <code>budget.timeout_ms</code></td></tr><tr><td>预算用量按 30 秒采样</td><td><code>budgetSampleIntervalMs</code> 默认 <code>30000</code> ms，两次采样之间可能已多消耗一些配额才触发取消</td><td>给预算留出余量；预算上限只能编程式注入，见<a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a></td></tr></tbody></table><h2 id="图与循环" tabindex="-1">图与循环 <a class="header-anchor" href="#图与循环" aria-label="Permalink to &quot;图与循环&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>循环组必须声明遍历硬上限</td><td><code>loop_groups[].max_traversals</code> 是必填（整数、≥ 1）：图声明里漏写会解析报错；用 <code>graph_add_loop</code> 时小于 1 会被直接拒绝</td><td>按「最多允许评审几轮」给一个明确的值</td></tr><tr><td>达到硬上限后升级而非继续</td><td>还有 <code>revise_needed</code> 但遍历次数已到 <code>max_traversals</code> 时，循环组以 <code>max_traversals exhausted</code> 升级（escalate），携带未解决项与遍历计数</td><td>提高 <code>max_traversals</code>；或检查上游节点为什么反复要求修订</td></tr><tr><td>连续两次相同收敛结果会被判为卡住</td><td>相邻遍历的收敛输出完全相同、累计达到 2 次时，循环组以 <code>stuck</code> 升级，且不再消耗遍历次数</td><td>让收敛节点的输出携带区分信息；或把不收敛的原因当成节点缺陷来修</td></tr><tr><td>图声明上的迭代上限字段不生效</td><td>在声明里写图级 <code>max_iterations</code> 不起作用——它只作为往返解析用的元数据保留；真正生效的是循环组的 <code>max_traversals</code></td><td>一律用 <code>max_traversals</code> 表达「最多几轮」</td></tr><tr><td><code>graph_add_loop</code> 的 <code>mode: &quot;fresh&quot;</code> 不受支持</td><td>想让每一轮循环在互相隔离的会话里执行时选择 <code>fresh</code>，会得到明确的错误而不是该行为</td><td>每一轮建一张独立的图来获得会话隔离；不需要隔离时用默认的 <code>inherit</code></td></tr><tr><td>循环次数与轮次开销有硬上限</td><td>未指定 <code>iterations</code> 时默认 5 轮；单次循环最多 50 轮；每个 dispatch 轮次最长 15 分钟；相邻轮次之间至少间隔 2 秒；送入摘要器的轮次输出与合并后的种子各上限 8000 字符</td><td>显式给 <code>iterations</code>；把长任务拆成多轮；把关键上下文写进文件或 artifact，避免被摘要截断</td></tr></tbody></table><h2 id="记忆系统" tabindex="-1">记忆系统 <a class="header-anchor" href="#记忆系统" aria-label="Permalink to &quot;记忆系统&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>默认返回条数有限</td><td><code>memory_list</code> 不给 <code>limit</code> 时最多返回 20 条摘要；<code>memory_recall</code> 不给 <code>limit</code> 时最多返回 10 条完整记录；会话启动时自动注入的记忆摘要上限为 10 条</td><td>显式传 <code>limit</code>；用 <code>scope</code>、<code>category</code>、<code>relevance</code> 过滤缩小范围</td></tr><tr><td>依赖 SQLite，Node 侧要求 ≥ 22.5</td><td>Node 运行时走 <code>node:sqlite</code>（自 Node 22.5 起提供）；Bun 运行时走 <code>bun:sqlite</code></td><td>用 Node 22.5 及以上，或直接用 Bun；记忆库启用 WAL 日志模式</td></tr><tr><td>全文检索依赖 SQLite FTS5 虚拟表</td><td>记忆库用 FTS5 建全文索引；所在运行时的 SQLite 未带 FTS5 时，建表与搜索都会失败</td><td>用 <code>bun:sqlite</code> 或 <code>node:sqlite</code> 自带的 SQLite（两者均支持 FTS5）；记忆库的驱动按运行时自动选择，没有配置项可换</td></tr></tbody></table><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>原生通知依赖平台命令行工具</td><td>平台命令不在 <code>PATH</code> 中时该通道<strong>静默跳过</strong>（不报错、不影响其它通道）</td><td>安装对应工具，或改用没有外部依赖的 <code>file</code> / <code>log</code> / <code>webhook</code> 通道</td></tr><tr><td>Webhook 默认 5 秒超时</td><td>目标端点响应慢于 5 秒时该次投递失败</td><td>换更快的端点；或改用 <code>custom-command</code> 通道自行控制超时</td></tr></tbody></table><p>平台命令对照：</p><table tabindex="0"><thead><tr><th>平台</th><th>SystemToast</th><th>Sound</th></tr></thead><tbody><tr><td>macOS</td><td><code>terminal-notifier</code>，缺失时回退 <code>osascript</code></td><td><code>afplay</code></td></tr><tr><td>Linux</td><td><code>notify-send</code></td><td><code>paplay</code>，缺失时回退 <code>aplay</code></td></tr><tr><td>Windows</td><td>PowerShell</td><td>PowerShell（<code>System.Media.SoundPlayer</code>）</td></tr></tbody></table><p>六个通道里，<code>file</code>（JSONL 追加写）、<code>log</code>（结构化日志）、<code>custom-command</code>（子进程，参数经环境变量传入）没有平台命令依赖；<code>webhook</code> 只要求网络可达。</p><h2 id="哈希行编辑" tabindex="-1">哈希行编辑 <a class="header-anchor" href="#哈希行编辑" aria-label="Permalink to &quot;哈希行编辑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>锚点会因外部改动失效</td><td>读取之后文件被别的进程（或你自己用其它工具）改过，<code>hashline_edit</code> 会报 anchor not found、version mismatch 或 hashWidth mismatch</td><td>按提示重新执行 <code>hashline_read</code> 取回新的锚点与版本号再改；不要跨编辑复用旧锚点</td></tr><tr><td>哈希宽度随文件大小变化</td><td>文件超过 1000 行后宽度由 2 位升到 3 位，超过 10000 行升到 4 位；用旧的宽度提交会报 hashWidth mismatch</td><td>用同一次读取返回的宽度；确需固定时用 <code>ROLEBOX_HASHLINE_WIDTH</code> 覆盖</td></tr><tr><td>校验格式固定为 2–8 位哈希</td><td>锚点必须写成 <code>行号#哈希</code>，哈希由字母、数字、<code>_</code>、<code>-</code> 组成且长度 2–8 位</td><td>直接复制读取结果里的锚点，不要手写</td></tr><tr><td>定位失败只在 ±10 行内模糊搜索</td><td>目标内容移动超过 10 行时模糊纠正找不到它，编辑失败</td><td>重新读取该区域；大范围移动后重建锚点</td></tr><tr><td>文件不存在时无法用锚点编辑</td><td>对不存在的文件做锚点替换会报 <code>File not found</code></td><td>用无锚点的追加 / 前插操作创建文件</td></tr></tbody></table><h2 id="外部工具依赖" tabindex="-1">外部工具依赖 <a class="header-anchor" href="#外部工具依赖" aria-label="Permalink to &quot;外部工具依赖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>LSP 功能要求本机装有语言服务器</td><td>注册表覆盖 TypeScript/JavaScript、Python、Go、Rust、C、C++、Java、Ruby、Bash、Lua、Kotlin；对应二进制不在 <code>PATH</code> 或常见安装目录时，该语言的诊断、跳转、补全不可用</td><td>安装对应服务器：<code>typescript-language-server</code>、<code>pyright-langserver</code>、<code>gopls</code>、<code>rust-analyzer</code>、<code>clangd</code>、<code>jdtls</code>、<code>solargraph</code>、<code>bash-language-server</code>、<code>lua-language-server</code>、<code>kotlin-lsp</code></td></tr><tr><td>JavaScript 渲染依赖可选包</td><td>未安装 Playwright 时，需要执行 JS 才能取到内容的页面退回静态 HTTP 抓取，抓到的内容不完整</td><td>安装 <code>playwright</code>；Crawlee 提供更进一步的爬取能力，同样可选</td></tr><tr><td>自定义 Hook 的清理不是强制的</td><td>Hook 模块没有导出 <code>onDispose</code> 时，关闭阶段不会为它调用任何清理逻辑</td><td>需要清理资源（子进程、临时文件、连接）的 Hook 请实现 <code>onDispose</code></td></tr></tbody></table><h2 id="平台差异" tabindex="-1">平台差异 <a class="header-anchor" href="#平台差异" aria-label="Permalink to &quot;平台差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>限制</th><th>什么情况下会撞上</th><th>规避方式</th></tr></thead><tbody><tr><td>恢复框架只在 opencode 上装配</td><td>在 pi 或 dsh 下配置 <code>hooks.recovery</code>，恢复策略与内置恢复 Hook 都不会运行</td><td>依赖自动恢复的能力放到 opencode；其它平台上按<a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a>里的手工步骤处理失败任务</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/rolebox-docs/03-Reference/error-handling.html">错误处理</a> — 每个故障场景的降级行为与排查步骤</li><li><a href="/rolebox-docs/03-Reference/dispatch-config.html">调度配置</a> — 上面出现的调度参数</li><li><a href="/rolebox-docs/04-Advanced/compatibility.html">兼容性</a> — harness 能力矩阵与破坏性变更</li></ul>',24)])])}const u=e(a,[["render",r]]);export{m as __pageData,u as default};
